import {ramp,contrast,rampExport} from './core.mjs';
export function rampTool({change,status}){const $=id=>document.getElementById(id);let color='#709f48',name='brand',rows=[];
  function draw(){rows=ramp(color);$('ramp-preview').replaceChildren();$('ramp-contrast').replaceChildren();for(const r of rows){const block=document.createElement('div');block.className='studio-ramp-swatch';block.style.background=r.color;block.style.color=contrast(r.color,'#000000')>=contrast(r.color,'#ffffff')?'#000000':'#ffffff';const n=document.createElement('span');n.textContent=r.level;const hex=document.createElement('code');hex.textContent=r.color;const label=document.createElement('small');label.textContent=r.white>=4.5?'White AA':'Black AA';block.append(n,hex,label);$('ramp-preview').append(block);const row=document.createElement('tr');for(const text of [r.level,r.color,`${r.white.toFixed(2)}:1 ${r.white>=4.5?'· AA':'· fails AA'}`,`${r.black.toFixed(2)}:1 ${r.black>=4.5?'· AA':'· fails AA'}`]){const cell=document.createElement('td');cell.textContent=text;row.append(cell)}$('ramp-contrast').append(row)}change()}
  $('ramp-colour').oninput=e=>{color=e.target.value;$('ramp-hex').value=color;$('ramp-hex').setCustomValidity('');draw()};$('ramp-hex').oninput=e=>{if(!/^#[a-f0-9]{6}$/i.test(e.target.value)){e.target.setCustomValidity('Use a six-digit hex colour, such as #709f48.');return}e.target.setCustomValidity('');color=e.target.value;$('ramp-colour').value=color;draw()};$('ramp-name').oninput=e=>{const valid=/^[a-z][a-z0-9-]{0,29}$/.test(e.target.value);e.target.setCustomValidity(valid?'':'Use lowercase letters, numbers and hyphens, starting with a letter.');if(valid){name=e.target.value;change()}};
  draw();return {get:()=>({color,name}),set:v=>{if(/^#[a-f0-9]{6}$/i.test(v?.color))color=v.color;if(typeof v?.name==='string'&&/^[a-z][a-z0-9-]{0,29}$/.test(v.name))name=v.name;$('ramp-colour').value=color;$('ramp-hex').value=color;$('ramp-name').value=name;draw()},export:format=>{if(!$('ramp-name').reportValidity()||!$('ramp-hex').reportValidity())throw Error('Fix the colour or token name before exporting.');return rampExport(rows,name,format)}};
}
